    _ab.typingScore = function() {
        var td = _ab._typingData;
        if (td.intervals.length < 5) return 30; // Not enough data
        // Calculate standard deviation of typing intervals
        var sum = 0;
        for (var i = 0; i < td.intervals.length; i++) sum += td.intervals[i];
        var mean = sum / td.intervals.length;
        var sqDiffSum = 0;
        for (var j = 0; j < td.intervals.length; j++) {
            sqDiffSum += Math.pow(td.intervals[j] - mean, 2);
        }
        var stdDev = Math.sqrt(sqDiffSum / td.intervals.length);

        // Bots have very low stdDev (uniform timing). Humans are messy (high stdDev).
        // Also: if mean < 20ms, that's inhuman speed
        if (mean < 20) return 0; // Machine gun typing
        if (stdDev < 10) return 5; // Robotic uniformity
        if (stdDev < 25) return 30;
        if (stdDev > 40) return 100; // Beautifully human
        return 60;
    };

    // ── 3. Scroll Behavior ───────────────────────────────────
    _ab._scrollData = { events: 0, depths: [], directions: 0, lastDir: 0 };
