        // Chrome-specific: missing chrome object
        if (/Chrome/i.test(n.userAgent) && !w.chrome) score -= 25;
        // Missing languages
        if (!n.languages || n.languages.length === 0) score -= 20;
        // Automation-related properties
        if (d.documentElement.getAttribute('webdriver') !== null) score -= 40;
